\title{The Analytic L-Function Census: Rigidity, Exactness, and Countability of Dirichlet Series}
\author{Aristotle}
\date{2026-07-11}

\begin{document}

\begin{abstract}
We study the universe of L-functions as genuine analytic objects rather than as
combinatorial packets of coefficient data. An L-function is realized concretely as a
Dirichlet series $L_f(s) = \sum_{n \ge 1} f(n) n^{-s}$ built from a coefficient
sequence $f : \mathbb{N} \to \mathbb{C}$ and viewed as a function of the complex
variable $s$ on a right half-plane of convergence. Our organizing result is a
\emph{rigidity theorem}: a Dirichlet series that converges somewhere is uniquely
determined by its coefficients. From this hub we derive four consequences.
(1) The Riemann zeta function is the unique normalized, somewhere-convergent Dirichlet
series taking its values. (2) The elementary ``monomial'' series $s \mapsto (k+1)^{-s}$
are pairwise distinct, so the analytic L-function universe is infinite. (3) For each
fixed modulus $N$, the Dirichlet characters modulo $N$ correspond bijectively to their
L-functions --- the census is exact, with no accidental coincidences. (4) The family of
all Dirichlet L-functions over all moduli is countable. Together these upgrade the
census principle --- \emph{an L-function is its data} --- from a modeling convention to
a theorem about the analytic functions themselves.
\end{abstract}

\maketitle

\section{Introduction}

L-functions are among the most information-dense objects in number theory. To an
arithmetic object --- an integer, a character, an elliptic curve, a modular form, an
automorphic representation --- one attaches a Dirichlet series whose analytic
properties encode deep arithmetic. The Langlands program holds, in one of its guiding
slogans, that L-functions \emph{classify} the objects that produce them.

The present work makes the most elementary form of that slogan precise and
self-contained. As we range over coefficient sequences and build the analytic functions
they define, when do two constructions yield the \emph{same} function, and how large is
the resulting universe? We define L-functions as actual functions $\mathbb{C} \to
\mathbb{C}$ and prove that the census principle is a \emph{theorem}: the map from
coefficient data to analytic function is injective on the convergent range. This
rigidity is the fulcrum on which uniqueness of $\zeta$, infinitude of the universe,
exactness of the Dirichlet census, and countability of the Dirichlet family all rest.

\section{Definitions and setup}

Throughout, coefficient sequences are functions $f : \mathbb{N} \to \mathbb{C}$, where
$\mathbb{N} = \{0, 1, 2, \dots\}$.

\begin{definition}[Dirichlet series / L-function]
For a coefficient sequence $f$, the associated \emph{Dirichlet series} or
\emph{L-function} is
\[
  L_f(s) = \sum_{n=1}^{\infty} \frac{f(n)}{n^s}, \qquad s \in \mathbb{C},
\]
defined at those $s$ for which the series converges. The $n = 0$ term is omitted;
correspondingly we call $f$ \emph{normalized} when $f(0) = 0$.
\end{definition}

\begin{definition}[Summability at a point]
The series is \emph{summable at $s$} if $\sum_{n \ge 1} |f(n)|\, n^{-\Rea s}$ converges.
\end{definition}

\begin{definition}[Abscissa of absolute convergence]
The \emph{abscissa of absolute convergence} $\sigma_a(f) \in [-\infty, +\infty]$ is the
infimum of the real parts $\Rea s$ at which the series is summable. If the series is
summable at some point then $\sigma_a(f) < +\infty$, and $L_f$ is holomorphic on
$\{\Rea s > \sigma_a(f)\}$. We say $f$ \emph{converges somewhere} when
$\sigma_a(f) < +\infty$.
\end{definition}

\begin{definition}[Dirichlet character]
For a modulus $N \ge 1$, a \emph{Dirichlet character} modulo $N$ is a homomorphism
$\chi : (\mathbb{Z}/N\mathbb{Z})^\times \to \mathbb{C}^\times$ extended to $\mathbb{Z}$
by $\chi(n) = 0$ when $\gcd(n, N) > 1$. Every value satisfies $|\chi(n)| \le 1$, and the
number of characters modulo $N$ equals Euler's totient $\varphi(N)$.
\end{definition}

\begin{definition}[Character coefficient sequence]
For a character $\chi$ modulo $N$, set $c_\chi(0) = 0$ and $c_\chi(n) = \chi(n \bmod N)$
for $n \ge 1$. Its L-function $L_{c_\chi}(s) = \sum_{n \ge 1} \chi(n) n^{-s}$ is the
\emph{Dirichlet L-function} $L(s, \chi)$.
\end{definition}

\section{The rigidity hub}

\begin{theorem}[Rigidity of L-functions]\label{thm:rigidity}
Let $f, g : \mathbb{N} \to \mathbb{C}$ be normalized ($f(0) = g(0) = 0$) and each
convergent somewhere. If $L_f = L_g$ as functions, then $f = g$. Equivalently,
$f \mapsto L_f$ is injective on normalized, somewhere-convergent coefficient sequences.
\end{theorem}

\begin{proof}[Proof sketch]
Let $h = f - g$, normalized and convergent somewhere, with $L_h = 0$ on a right
half-plane. Suppose $h$ is not identically zero and let $m \ge 1$ be minimal with
$h(m) \ne 0$. Multiplying $\sum_{n \ge m} h(n) n^{-s} = 0$ by $m^s$ gives
\[
  h(m) + \sum_{n > m} h(n)\Big(\tfrac{m}{n}\Big)^{s} = 0.
\]
Each ratio $m/n < 1$, so $(m/n)^s \to 0$ as $\Rea s \to +\infty$, and the tail is
dominated by a fixed convergent series; letting $\Rea s \to +\infty$ forces
$h(m) = 0$, a contradiction. Hence $h \equiv 0$ and $f = g$.
\end{proof}

\begin{lemma}[Convergence from a single summable point]\label{lem:conv-point}
If the Dirichlet series of $f$ is summable at some $s_0$, then $\sigma_a(f) < +\infty$.
\end{lemma}

\begin{proof}[Proof sketch]
Summability at $s_0$ places $\sigma_a(f) \le \Rea s_0 < +\infty$.
\end{proof}

\begin{lemma}[Convergence from bounded coefficients]\label{lem:conv-bdd}
If $|f(n)| \le m$ for all $n \ge 1$, then the series is summable for every $s$ with
$\Rea s > 1$; in particular $\sigma_a(f) < +\infty$.
\end{lemma}

\begin{proof}[Proof sketch]
For $\Rea s > 1$, $\sum_{n \ge 1} |f(n)| n^{-\Rea s} \le m \sum_{n \ge 1} n^{-\Rea s}
< \infty$, a convergent $p$-series; apply Lemma~\ref{lem:conv-point} at $s = 2$.
\end{proof}

\section{Uniqueness of the Riemann zeta function}

\begin{definition}[Zeta coefficients]
Let $z(n) = 1$ for $n \ge 1$ and $z(0) = 0$, so $L_z(s) = \sum_{n \ge 1} n^{-s} =
\zeta(s)$. Since $|z(n)| \le 1$, Lemma~\ref{lem:conv-bdd} gives $\sigma_a(z) < \infty$.
\end{definition}

\begin{theorem}[Rigidity of $\zeta$]\label{thm:zeta}
Let $g$ be normalized and convergent somewhere. If $L_g = \zeta$, then $g(n) = 1$ for
all $n \ge 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:rigidity} to $g$ and $z$.
\end{proof}

\section{The monomial family and infinitude}

\begin{definition}[Monomial / spike sequences]
For $k \in \mathbb{N}$ set $\operatorname{spike}_k(n) = 1$ if $n = k+1$ and $0$
otherwise. It is normalized and bounded by $1$, so $\sigma_a(\operatorname{spike}_k) <
\infty$, and $L_{\operatorname{spike}_k}(s) = (k+1)^{-s}$.
\end{definition}

\begin{lemma}[Distinct spikes]\label{lem:spike-inj}
The map $k \mapsto \operatorname{spike}_k$ is injective.
\end{lemma}

\begin{proof}[Proof sketch]
If $a \ne b$, then $\operatorname{spike}_a(a+1) = 1 \ne 0 = \operatorname{spike}_b(a+1)$.
\end{proof}

\begin{theorem}[Infinitude of the analytic universe]\label{thm:infinite}
The map $k \mapsto L_{\operatorname{spike}_k}$ is injective, so
$\{\, s \mapsto (k+1)^{-s} : k \in \mathbb{N}\,\}$ is an infinite family of pairwise
distinct analytic functions.
\end{theorem}

\begin{proof}[Proof sketch]
If $L_{\operatorname{spike}_a} = L_{\operatorname{spike}_b}$, then by
Theorem~\ref{thm:rigidity} $\operatorname{spike}_a = \operatorname{spike}_b$, so by
Lemma~\ref{lem:spike-inj} $a = b$. An injective $\mathbb{N}$-indexed family has infinite
range.
\end{proof}

\section{The Dirichlet census: exactness and countability}

\begin{lemma}[Boundedness and convergence of $c_\chi$]\label{lem:char-bdd}
For any character $\chi$ modulo $N$, $c_\chi$ is normalized with $|c_\chi(n)| \le 1$ for
$n \ge 1$; hence $\sigma_a(c_\chi) < \infty$.
\end{lemma}

\begin{proof}[Proof sketch]
$c_\chi(0) = 0$ and $|c_\chi(n)| = |\chi(n \bmod N)| \le 1$; apply
Lemma~\ref{lem:conv-bdd}.
\end{proof}

\begin{theorem}[Exactness of the census per modulus]\label{thm:exact}
Fix $N \ge 1$. The map $\chi \mapsto L(s,\chi) = L_{c_\chi}$ is injective on Dirichlet
characters modulo $N$, hence induces a bijection between the characters modulo $N$ and
their L-functions. In particular there are exactly $\varphi(N)$ distinct Dirichlet
L-functions of modulus $N$.
\end{theorem}

\begin{proof}[Proof sketch]
If $L(s,\chi_1) = L(s,\chi_2)$, Theorem~\ref{thm:rigidity} (via
Lemma~\ref{lem:char-bdd}) gives $c_{\chi_1} = c_{\chi_2}$, so $\chi_1(n) = \chi_2(n)$
for all $n$, i.e. $\chi_1 = \chi_2$. Surjectivity onto the image is automatic; the count
is the number of characters, $\varphi(N)$.
\end{proof}

\begin{theorem}[Countability of the Dirichlet family]\label{thm:countable}
The family $\mathcal{D} = \{\, L(s,\chi) : N \ge 1,\ \chi \text{ mod } N\,\}$ of all
Dirichlet L-functions is countable.
\end{theorem}

\begin{proof}[Proof sketch]
For each $N$ there are $\varphi(N) < \infty$ characters, hence finitely many
L-functions; $\mathcal{D}$ is a countable union of finite sets and so is countable.
\end{proof}

\section{Algorithms}

\subsection*{Coefficient recovery} The proof of rigidity is a peeling argument that runs
as an algorithm: given oracle access to $L_f$,
\[
  f(1) = \lim_{\sigma \to \infty} L_f(\sigma), \qquad
  f(m) = \lim_{\sigma \to \infty} m^{\sigma}\Big(L_f(\sigma) - \textstyle\sum_{n<m}
  f(n) n^{-\sigma}\Big),
\]
recovering coefficients one at a time.

\subsection*{Per-modulus enumeration} List residues coprime to $N$, form
$(\mathbb{Z}/N\mathbb{Z})^\times$, enumerate its $\varphi(N)$ characters; each yields one
L-function, with no duplicates by Theorem~\ref{thm:exact}.

\subsection*{Global enumeration} Dovetail over $N = 1, 2, 3, \dots$, outputting the
$\varphi(N)$ L-functions of each modulus, realizing Theorem~\ref{thm:countable}.

\section{Applications and discussion}

Rigidity licenses the standard technique of proving arithmetic objects equal by matching
their L-functions, and it is the toy model of ``strong multiplicity one''. Exactness and
countability are the ground-floor guarantees behind tabulating L-functions into
searchable catalogs. Theorem~\ref{thm:zeta} shows $\zeta$ has no competing Dirichlet
representation. The results concern the degree-one stratum; the same principle governs
higher strata, where convergence requires deeper coefficient bounds.

\section{Future directions}

\begin{enumerate}
\item \textbf{Cross-modulus faithfulness.} Injectivity of $\langle N, \chi\rangle
  \mapsto L(s,\chi)$ across moduli on primitive characters.
\item \textbf{Euler product.} Formalize $L(s,\chi) = \prod_p (1 - \chi(p) p^{-s})^{-1}$
  for $\Rea s > 1$ for a multiplicative uniqueness proof.
\item \textbf{Degree-two stratum.} Extend rigidity to modular forms and elliptic curves,
  using the Ramanujan bound $|a_p| \le 2\sqrt{p}$ to secure convergence.
\item \textbf{Selberg-class link.} Prove the classifying map from analytic L-function to
  its invariant packet is well-defined and injective on a convergent arithmetic
  subclass.
\item \textbf{Quantitative census.} Compute the character count $\varphi(N)$ per modulus
  and transport it along the per-modulus bijection.
\end{enumerate}

\section{Conclusion}

A somewhere-convergent Dirichlet series is uniquely determined by its coefficients. This
single principle makes the Riemann zeta representation unique, the monomial family
witness infinitude, the Dirichlet census exact modulus by modulus, and the full
Dirichlet family countable. The slogan ``an L-function is its data'' is thereby promoted
from a convenient model to a proved property of the analytic universe.

\end{document}

