import cmath

def monomial_value(k: int, s: complex) -> complex:
    """L-function of the spike coefficient sequence: s -> (k+1)^{-s}."""
    return cmath.exp(-s * cmath.log(k + 1))

s = complex(1.5, 0.7)
vals = [monomial_value(k, s) for k in range(8)]
for k, v in enumerate(vals):
    print(f"k={k}: (k+1)^(-s) = {v:.5f}")
distinct = len({(round(v.real, 8), round(v.imag, 8)) for v in vals})
print(f"distinct values: {distinct}/{len(vals)}  -> universe is infinite")

