def euler_phi(n: int) -> int:
    if n <= 1:
        return 1
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result

print(f"{'N':>3} | {'phi(N) = # distinct L-functions':>32}")
for N in range(1, 16):
    print(f"{N:>3} | {euler_phi(N):>32}")

