from __future__ import annotations
import math

def euler_phi(n: int) -> int:
    """Euler's totient phi(n): the number of Dirichlet characters modulo n,
    equivalently the count of 1 <= k <= n with gcd(k, n) = 1."""
    if n <= 1:
        return 1
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result

def census_counts(n_moduli: int) -> list[tuple[int, int, int]]:
    """Return (N, phi(N), cumulative) realizing the dovetailed enumeration of the
    countable Dirichlet family: exactly phi(N) L-functions occur at modulus N."""
    out, cum = [], 0
    for N in range(1, n_moduli + 1):
        phi = euler_phi(N)
        cum += phi
        out.append((N, phi, cum))
    return out

